insert into public.directory_entities(legacy_code,slug,name_ar,name_en,entity_type,description,website_url,primary_area_id,verification_status,public_visible,last_verified_at)
select value->>0,value->>1,value->>2,value->>3,value->>4,value->>5,value->>6,a.id,'needs_review',false,'2026-11-02'::date
from x left join public.directory_areas a on a.slug=value->>7
