commit;

begin;
-- Remove the broad ALL policy on public-facing directory tables to avoid overlapping SELECT policies.
drop policy if exists directory_areas_admin_all on public.directory_areas;
drop policy if exists directory_entities_admin_all on public.directory_entities;
drop policy if exists directory_projects_admin_all on public.directory_projects;
drop policy if exists directory_sources_admin_all on public.directory_sources;
drop policy if exists directory_project_entities_admin_all on public.directory_project_entities;
drop policy if exists directory_entity_sources_admin_all on public.directory_entity_sources;
drop policy if exists directory_project_sources_admin_all on public.directory_project_sources;
drop policy if exists directory_opportunities_admin_all on public.directory_opportunities;
drop policy if exists directory_opportunity_sources_admin_all on public.directory_opportunity_sources;

drop policy if exists directory_areas_public_read on public.directory_areas;
drop policy if exists directory_entities_public_read on public.directory_entities;
drop policy if exists directory_projects_public_read on public.directory_projects;
drop policy if exists directory_sources_public_read on public.directory_sources;
drop policy if exists directory_project_entities_public_read on public.directory_project_entities;
drop policy if exists directory_entity_sources_public_read on public.directory_entity_sources;
drop policy if exists directory_project_sources_public_read on public.directory_project_sources;
drop policy if exists directory_opportunities_public_read on public.directory_opportunities;
drop policy if exists directory_opportunity_sources_public_read on public.directory_opportunity_sources;

-- Anonymous public catalogue read.
create policy directory_areas_anon_read on public.directory_areas for select to anon
using(is_active and public_visible and verification_status='published');
create policy directory_entities_anon_read on public.directory_entities for select to anon
using(public_visible and verification_status='published');
create policy directory_projects_anon_read on public.directory_projects for select to anon
using(public_visible and verification_status='published');
create policy directory_sources_anon_read on public.directory_sources for select to anon
using(is_public);
create policy directory_project_entities_anon_read on public.directory_project_entities for select to anon
using(exists(select 1 from public.directory_projects p where p.id=project_id and p.public_visible and p.verification_status='published')
  and exists(select 1 from public.directory_entities e where e.id=entity_id and e.public_visible and e.verification_status='published'));
create policy directory_entity_sources_anon_read on public.directory_entity_sources for select to anon
using(exists(select 1 from public.directory_entities e where e.id=entity_id and e.public_visible and e.verification_status='published')
  and exists(select 1 from public.directory_sources s where s.id=source_id and s.is_public));
create policy directory_project_sources_anon_read on public.directory_project_sources for select to anon
using(exists(select 1 from public.directory_projects p where p.id=project_id and p.public_visible and p.verification_status='published')
  and exists(select 1 from public.directory_sources s where s.id=source_id and s.is_public));
create policy directory_opportunities_anon_read on public.directory_opportunities for select to anon
using(public_visible and verification_status='published');
create policy directory_opportunity_sources_anon_read on public.directory_opportunity_sources for select to anon
using(exists(select 1 from public.directory_opportunities o where o.id=opportunity_id and o.public_visible and o.verification_status='published')
  and exists(select 1 from public.directory_sources s where s.id=source_id and s.is_public));

-- Signed-in users get the same public records; only true admins get draft/private catalogue rows.
create policy directory_areas_authenticated_read on public.directory_areas for select to authenticated
using((is_active and public_visible and verification_status='published') or (select public.layan_is_admin()));
create policy directory_entities_authenticated_read on public.directory_entities for select to authenticated
using((public_visible and verification_status='published') or (select public.layan_is_admin()));
create policy directory_projects_authenticated_read on public.directory_projects for select to authenticated
using((public_visible and verification_status='published') or (select public.layan_is_admin()));
create policy directory_sources_authenticated_read on public.directory_sources for select to authenticated
using(is_public or (select public.layan_is_admin()));
create policy directory_project_entities_authenticated_read on public.directory_project_entities for select to authenticated
using((exists(select 1 from public.directory_projects p where p.id=project_id and p.public_visible and p.verification_status='published')
  and exists(select 1 from public.directory_entities e where e.id=entity_id and e.public_visible and e.verification_status='published'))
  or (select public.layan_is_admin()));
create policy directory_entity_sources_authenticated_read on public.directory_entity_sources for select to authenticated
using((exists(select 1 from public.directory_entities e where e.id=entity_id and e.public_visible and e.verification_status='published')
  and exists(select 1 from public.directory_sources s where s.id=source_id and s.is_public))
  or (select public.layan_is_admin()));
create policy directory_project_sources_authenticated_read on public.directory_project_sources for select to authenticated
using((exists(select 1 from public.directory_projects p where p.id=project_id and p.public_visible and p.verification_status='published')
  and exists(select 1 from public.directory_sources s where s.id=source_id and s.is_public))
  or (select public.layan_is_admin()));
create policy directory_opportunities_authenticated_read on public.directory_opportunities for select to authenticated
using((public_visible and verification_status='published') or (select public.layan_is_admin()));
create policy directory_opportunity_sources_authenticated_read on public.directory_opportunity_sources for select to authenticated
using((exists(select 1 from public.directory_opportunities o where o.id=opportunity_id and o.public_visible and o.verification_status='published')
  and exists(select 1 from public.directory_sources s where s.id=source_id and s.is_public))
  or (select public.layan_is_admin()));

-- Separate admin writes; no writes for ordinary signed-in users.
create policy directory_areas_admin_insert on public.directory_areas for insert to authenticated with check((select public.layan_is_admin()));
create policy directory_areas_admin_update on public.directory_areas for update to authenticated using((select public.layan_is_admin())) with check((select public.layan_is_admin()));
create policy directory_areas_admin_delete on public.directory_areas for delete to authenticated using((select public.layan_is_admin()));
create policy directory_entities_admin_insert on public.directory_entities for insert to authenticated with check((select public.layan_is_admin()));
create policy directory_entities_admin_update on public.directory_entities for update to authenticated using((select public.layan_is_admin())) with check((select public.layan_is_admin()));
create policy directory_entities_admin_delete on public.directory_entities for delete to authenticated using((select public.layan_is_admin()));
create policy directory_projects_admin_insert on public.directory_projects for insert to authenticated with check((select public.layan_is_admin()));
create policy directory_projects_admin_update on public.directory_projects for update to authenticated using((select public.layan_is_admin())) with check((select public.layan_is_admin()));
create policy directory_projects_admin_delete on public.directory_projects for delete to authenticated using((select public.layan_is_admin()));
create policy directory_sources_admin_insert on public.directory_sources for insert to authenticated with check((select public.layan_is_admin()));
create policy directory_sources_admin_update on public.directory_sources for update to authenticated using((select public.layan_is_admin())) with check((select public.layan_is_admin()));
create policy directory_sources_admin_delete on public.directory_sources for delete to authenticated using((select public.layan_is_admin()));
