  update public.supplier_ads
  set status = 'active',
      price = 0,
      starts_at = now(),
      ends_at = now() + interval '30 days',
      free_trial_started_at = now(),
      free_trial_ends_at = now() + interval '30 days',
      updated_at = now()
  where id = p_ad_id;

  return jsonb_build_object('success', true, 'ad_id', p_ad_id, 'status', 'active', 'trial_days', 30);
end;
