-- Incremental ASYUT AQAR migration: directory admin atomic mutation + audit log.
-- Depends on the catalog-derived baseline migration immediately preceding this file.
-- This is an app schema migration; it is safe to replay only on a clean local database.
-- Do not push to the populated production project until a separate migration-ledger
-- reconciliation has been reviewed and explicitly approved.

CREATE OR REPLACE FUNCTION public.directory_admin_mutate_with_audit(
  p_table_name text,
  p_operation text,
  p_record_id uuid,
  p_data jsonb,
  p_reason text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE
  v_allowed_columns text[];
  v_key text;
  v_assignments text;
  v_columns text;
  v_values text;
  v_before jsonb;
  v_after jsonb;
  v_old_values jsonb := '{}'::jsonb;
  v_new_values jsonb;
  v_audit_record_id uuid;
  v_audit_id uuid;
  v_expected_owner_id uuid;
BEGIN
  IF auth.uid() IS NULL OR NOT public.layan_is_admin() THEN
    RAISE EXCEPTION 'مسؤول قاعدة البيانات فقط يمكنه تنفيذ هذه العملية.'
      USING ERRCODE = '42501';
  END IF;

  IF p_data IS NULL
     OR jsonb_typeof(p_data) <> 'object'
     OR p_data = '{}'::jsonb THEN
    RAISE EXCEPTION 'بيانات العملية يجب أن تكون كائن JSON غير فارغ.'
      USING ERRCODE = '22023';
  END IF;

  IF p_operation = 'update' THEN
    IF p_record_id IS NULL THEN
      RAISE EXCEPTION 'معرّف السجل مطلوب للتعديل.'
        USING ERRCODE = '22023';
    END IF;

    CASE p_table_name
      WHEN 'directory_entities' THEN
        v_allowed_columns := ARRAY[
          'name_ar','name_en','description','website_url','public_phone',
          'public_email','public_address','primary_area_id','public_visible',
          'verification_status','last_verified_at','next_review_at'
        ];
      WHEN 'directory_projects' THEN
        v_allowed_columns := ARRAY[
          'name_ar','name_en','description','location_text','area_id',
          'project_status','public_visible','verification_status',
          'last_verified_at','next_review_at'
        ];
      WHEN 'directory_areas' THEN
        v_allowed_columns := ARRAY[
          'name_ar','name_en','slug','area_type','description','notes',
          'is_active','public_visible','verification_status',
          'last_verified_at','next_review_at'
        ];
      WHEN 'directory_opportunities' THEN
        v_allowed_columns := ARRAY[
          'name_ar','city','activity','announcement_date','opportunity_type',
          'source_claimed_status','size_description','terms_as_published',
          'notes','public_visible','verification_status'
        ];
      WHEN 'directory_sources' THEN
        v_allowed_columns := ARRAY[
          'title','publisher','source_type','source_url','publication_date',
          'confidence_level','notes','is_public'
        ];
      ELSE
        RAISE EXCEPTION 'هذا الجدول غير مسموح بالتعديل من هذه الواجهة.'
          USING ERRCODE = '22023';
    END CASE;

  ELSIF p_operation = 'insert' THEN
    CASE p_table_name
      WHEN 'directory_sources' THEN
        IF p_record_id IS NOT NULL THEN
          RAISE EXCEPTION 'لا ترسل معرّف سجل عند إضافة مصدر جديد.'
            USING ERRCODE = '22023';
        END IF;
        v_allowed_columns := ARRAY[
          'title','publisher','source_type','source_url','publication_date',
          'confidence_level','is_public','notes'
        ];
      WHEN 'directory_entity_sources' THEN
        v_allowed_columns := ARRAY['entity_id','source_id','claim_key'];
        v_expected_owner_id := NULLIF(p_data ->> 'entity_id', '')::uuid;
      WHEN 'directory_project_sources' THEN
        v_allowed_columns := ARRAY['project_id','source_id','claim_key'];
        v_expected_owner_id := NULLIF(p_data ->> 'project_id', '')::uuid;
      WHEN 'directory_opportunity_sources' THEN
        v_allowed_columns := ARRAY['opportunity_id','source_id','claim_key'];
        v_expected_owner_id := NULLIF(p_data ->> 'opportunity_id', '')::uuid;
      ELSE
        RAISE EXCEPTION 'هذا الجدول غير مسموح بالإضافة من هذه الواجهة.'
          USING ERRCODE = '22023';
    END CASE;

    IF p_table_name <> 'directory_sources'
       AND (p_record_id IS NULL OR v_expected_owner_id IS DISTINCT FROM p_record_id) THEN
      RAISE EXCEPTION 'معرّف السجل المرتبط بالمصدر غير مطابق.'
        USING ERRCODE = '22023';
    END IF;

  ELSE
    RAISE EXCEPTION 'نوع العملية غير مدعوم.'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_object_keys(p_data) AS supplied(key_name)
    WHERE NOT (supplied.key_name = ANY(v_allowed_columns))
  ) THEN
    RAISE EXCEPTION 'تحتوي البيانات على حقل غير مسموح لهذه العملية.'
      USING ERRCODE = '22023';
  END IF;

  IF p_operation = 'update' THEN
    EXECUTE format(
      'SELECT to_jsonb(target) FROM public.%I AS target WHERE target.id = $1 FOR UPDATE',
      p_table_name
    )
    INTO v_before
    USING p_record_id;

    IF v_before IS NULL THEN
      RAISE EXCEPTION 'السجل المطلوب غير موجود.'
        USING ERRCODE = 'P0002';
    END IF;

    SELECT string_agg(
      format(
        '%I = (jsonb_populate_record(NULL::public.%I, $2)).%I',
        supplied.key_name,
        p_table_name,
        supplied.key_name
      ),
      ', '
      ORDER BY supplied.key_name
    )
    INTO v_assignments
    FROM jsonb_object_keys(p_data) AS supplied(key_name);

    EXECUTE format(
      'UPDATE public.%I AS target SET %s WHERE target.id = $1 RETURNING to_jsonb(target)',
      p_table_name,
      v_assignments
    )
    INTO v_after
    USING p_record_id, p_data;

    SELECT COALESCE(
      jsonb_object_agg(supplied.key_name, v_before -> supplied.key_name),
      '{}'::jsonb
    )
    INTO v_old_values
    FROM jsonb_object_keys(p_data) AS supplied(key_name);

    SELECT COALESCE(
      jsonb_object_agg(supplied.key_name, v_after -> supplied.key_name),
      '{}'::jsonb
    )
    INTO v_new_values
    FROM jsonb_object_keys(p_data) AS supplied(key_name);

    v_audit_record_id := p_record_id;

  ELSE
    SELECT
      string_agg(format('%I', supplied.key_name), ', ' ORDER BY supplied.key_name),
      string_agg(
        format(
          '(jsonb_populate_record(NULL::public.%I, $1)).%I',
          p_table_name,
          supplied.key_name
        ),
        ', '
        ORDER BY supplied.key_name
      )
    INTO v_columns, v_values
    FROM jsonb_object_keys(p_data) AS supplied(key_name);

    EXECUTE format(
      'INSERT INTO public.%I AS target (%s) VALUES (%s) RETURNING to_jsonb(target)',
      p_table_name,
      v_columns,
      v_values
    )
    INTO v_after
    USING p_data;

    v_new_values := v_after;

    IF p_table_name = 'directory_sources' THEN
      v_audit_record_id := (v_after ->> 'id')::uuid;
    ELSE
      v_audit_record_id := p_record_id;
    END IF;
  END IF;

  IF v_audit_record_id IS NULL OR v_after IS NULL THEN
    RAISE EXCEPTION 'لم يكتمل حفظ السجل قبل تسجيل أثر العملية.'
      USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.directory_change_log (
    table_name,
    record_id,
    changed_by,
    old_values,
    new_values,
    reason
  )
  VALUES (
    p_table_name,
    v_audit_record_id,
    auth.uid(),
    v_old_values,
    v_new_values,
    LEFT(
      COALESCE(
        NULLIF(BTRIM(p_reason), ''),
        CASE WHEN p_operation = 'insert' THEN 'إضافة سجل من لوحة إدارة الدليل'
             ELSE 'تعديل سجل من لوحة إدارة الدليل' END
      ),
      240
    )
  )
  RETURNING id INTO v_audit_id;

  RETURN jsonb_build_object(
    'record', v_after,
    'audit_id', v_audit_id
  );
END;
$function$;

-- Add an opt-in for notifications about every newly published property offer.
-- Existing subscribers keep their current matching-alert setting; general alerts default off.
ALTER TABLE public.buyer_preferences
  ADD COLUMN IF NOT EXISTS all_notifications_enabled boolean NOT NULL DEFAULT false;

COMMENT ON COLUMN public.buyer_preferences.all_notifications_enabled IS
  'Whether this buyer wants an in-app and push alert for every newly published property offer, in addition to optional preference-matched alerts.';

create table public.company_claim_requests (
  id uuid primary key default gen_random_uuid(),
  directory_entity_id uuid not null references public.directory_entities(id) on delete restrict,
  requester_user_id uuid not null references auth.users(id) on delete cascade,
  representative_name text not null check (char_length(btrim(representative_name)) between 3 and 120),
  representative_role text not null check (char_length(btrim(representative_role)) between 2 and 80),
  contact_phone text not null check (
    char_length(btrim(contact_phone)) between 7 and 30
    and char_length(regexp_replace(contact_phone, '[^0-9]', '', 'g')) between 7 and 20
  ),
  contact_email text check (contact_email is null or char_length(btrim(contact_email)) <= 160),
  notes text check (notes is null or char_length(notes) <= 600),
  status text not null default 'pending'
    check (status in ('pending', 'approved', 'rejected')),
  admin_notes text,
  reviewed_by uuid references auth.users(id) on delete set null,
  reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public.company_claim_requests is
  'Private company-directory claim requests. Submitted by authenticated accounts and reviewed by ASYUT AQAR admins.';
comment on column public.company_claim_requests.requester_user_id is
  'Authenticated Supabase user who submitted the request. Never accepted from user-editable metadata.';
comment on column public.company_claim_requests.admin_notes is
  'Internal review notes; visible only to the requester for their own request and platform admins.';

create index company_claim_requests_status_created_idx
  on public.company_claim_requests (status, created_at asc);
create index company_claim_requests_entity_idx
  on public.company_claim_requests (directory_entity_id, created_at desc);
create unique index company_claim_requests_one_pending_per_user_entity
  on public.company_claim_requests (directory_entity_id, requester_user_id)
  where status = 'pending';

create table public.company_entity_managers (
  directory_entity_id uuid primary key references public.directory_entities(id) on delete restrict,
  owner_user_id uuid not null references auth.users(id) on delete cascade,
  claim_request_id uuid not null unique references public.company_claim_requests(id) on delete restrict,
  approved_by uuid references auth.users(id) on delete set null,
  approved_at timestamptz not null default now()
);

comment on table public.company_entity_managers is
  'Verified account-to-directory-entity links created only by the protected admin approval function. Does not grant direct write access to directory_entities.';

alter table public.company_claim_requests enable row level security;
alter table public.company_entity_managers enable row level security;

revoke all on table public.company_claim_requests from public, anon, authenticated;
grant select, insert on table public.company_claim_requests to authenticated;

create policy company_claim_requests_read_own_or_admin
  on public.company_claim_requests
  for select to authenticated
  using (
    requester_user_id = (select auth.uid())
    or public.layan_is_admin()
  );

create policy company_claim_requests_insert_own_pending
  on public.company_claim_requests
  for insert to authenticated
  with check (
    requester_user_id = (select auth.uid())
    and status = 'pending'
    and reviewed_by is null
    and reviewed_at is null
    and admin_notes is null
    and exists (
      select 1
      from public.directory_entities e
      where e.id = directory_entity_id
        and e.public_visible = true
        and e.verification_status = 'published'
    )
  );

revoke all on table public.company_entity_managers from public, anon, authenticated;
grant select on table public.company_entity_managers to authenticated;

create policy company_entity_managers_read_own_or_admin
  on public.company_entity_managers
  for select to authenticated
  using (
    owner_user_id = (select auth.uid())
    or public.layan_is_admin()
  );

create or replace function private.company_claim_admin_list()
returns table (
  id uuid,
  directory_entity_id uuid,
  company_name text,
  requester_user_id uuid,
  representative_name text,
  representative_role text,
  contact_phone text,
  contact_email text,
  notes text,
  status text,
  admin_notes text,
  created_at timestamptz,
  reviewed_at timestamptz,
  reviewed_by uuid
)
language plpgsql
stable
security definer
set search_path = ''
as $function$
begin
  if auth.uid() is null or not private.layan_is_admin() then
    raise exception 'هذه الطلبات متاحة لإدارة أسيوط عقار فقط' using errcode = '42501';
  end if;

  return query
    select
      c.id,
      c.directory_entity_id,
      e.name_ar::text,
      c.requester_user_id,
      c.representative_name,
      c.representative_role,
      c.contact_phone,
      c.contact_email,
      c.notes,
      c.status,
      c.admin_notes,
      c.created_at,
      c.reviewed_at,
      c.reviewed_by
    from public.company_claim_requests c
    join public.directory_entities e on e.id = c.directory_entity_id
    where c.status = 'pending'
    order by c.created_at asc;
end;
$function$;

create or replace function private.company_claim_admin_review(
  p_id uuid,
  p_action text,
  p_note text default null
)
returns text
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_request public.company_claim_requests%rowtype;
  v_existing_owner uuid;
  v_note text := nullif(left(btrim(coalesce(p_note, '')), 1000), '');
begin
  if auth.uid() is null or not private.layan_is_admin() then
    raise exception 'هذا الإجراء متاح لإدارة أسيوط عقار فقط' using errcode = '42501';
  end if;

  if p_action not in ('approve', 'request_info', 'reject') then
    raise exception 'الإجراء المطلوب غير صحيح' using errcode = '22023';
  end if;

  select *
    into v_request
    from public.company_claim_requests
   where id = p_id and status = 'pending'
   for update;

  if not found then
    raise exception 'الطلب غير موجود أو تم البت فيه بالفعل' using errcode = 'P0002';
  end if;

  if p_action in ('request_info', 'reject') and char_length(coalesce(v_note, '')) < 3 then
    raise exception 'اكتب ملاحظة واضحة من 3 أحرف على الأقل' using errcode = '22023';
  end if;

  if p_action = 'approve' then
    select m.owner_user_id
      into v_existing_owner
      from public.company_entity_managers m
     where m.directory_entity_id = v_request.directory_entity_id;

    if found and v_existing_owner <> v_request.requester_user_id then
      raise exception 'هذا الملف مرتبط بالفعل بحساب ممثل آخر؛ راجع الإدارة قبل أي تغيير' using errcode = '23505';
    end if;

    insert into public.company_entity_managers (
      directory_entity_id, owner_user_id, claim_request_id, approved_by, approved_at
    )
    values (
      v_request.directory_entity_id, v_request.requester_user_id, v_request.id, auth.uid(), now()
    )
    on conflict (directory_entity_id) do nothing;

    update public.company_claim_requests
       set status = 'approved',
           admin_notes = case when v_note is null then admin_notes else concat_ws(E'\n\n', nullif(admin_notes, ''), v_note) end,
           reviewed_by = auth.uid(),
           reviewed_at = now(),
           updated_at = now()
     where id = v_request.id;

    return 'approved';
  elsif p_action = 'request_info' then
    update public.company_claim_requests
       set admin_notes = concat_ws(E'\n\n', nullif(admin_notes, ''), v_note),
           reviewed_by = auth.uid(),
           reviewed_at = now(),
           updated_at = now()
     where id = v_request.id;

    return 'info_requested';
  else
    update public.company_claim_requests
       set status = 'rejected',
           admin_notes = concat_ws(E'\n\n', nullif(admin_notes, ''), v_note),
           reviewed_by = auth.uid(),
           reviewed_at = now(),
           updated_at = now()
     where id = v_request.id;

    return 'rejected';
  end if;
end;
$function$;

